#!/usr/bin/env bash
set -euo pipefail
INPUT_DIR="${INPUT_DIR:-/data/voxel_csv_combined}"; OUTPUT_DIR="${OUTPUT_DIR:-/outputs/poleline_voxel_run_session_groups/v62_three_stage/inference_custom}"; MODEL_PATH="${MODEL_PATH:-/outputs/poleline_voxel_run_session_groups/v62_three_stage/selected/v6_stage1_selected.pt}"; CALIBRATION_JSON="${CALIBRATION_JSON:-/outputs/poleline_voxel_run_session_groups/v62_three_stage/selected/calibration.json}"; LOCAL_REFINER_BUNDLE="${LOCAL_REFINER_BUNDLE:-/outputs/poleline_voxel_run_session_groups/v62_three_stage/stage2_refiner/local_refiner_bundle.joblib}"; MANIFEST_JSON="${MANIFEST_JSON:-}"; GRID_SIZE="${GRID_SIZE:-400 400 200}"
mkdir -p "$OUTPUT_DIR"; LOG="$OUTPUT_DIR/v62_inference_$(date +%Y%m%d_%H%M%S).log"; exec > >(tee -a "$LOG") 2>&1
manifest=(); [[ -n "$MANIFEST_JSON" ]] && manifest=(--manifest_json "$MANIFEST_JSON")
python infer_v62_stage1_stage2.py --input_dir "$INPUT_DIR" --output_dir "$OUTPUT_DIR" --model_path "$MODEL_PATH" --calibration_json "$CALIBRATION_JSON" --local_refiner_bundle "$LOCAL_REFINER_BUNDLE" "${manifest[@]}" --grid_size $GRID_SIZE --voxel_size_ft "${VOXEL_SIZE_FT:-0.5}" --pole_candidate_threshold "${POLE_CANDIDATE_THRESHOLD:-0.15}" --line_candidate_threshold "${LINE_CANDIDATE_THRESHOLD:-0.08}" --line_weak_threshold "${LINE_WEAK_THRESHOLD:-0.04}" --line_competition_ratio "${LINE_COMPETITION_RATIO:-0.55}" --line_min_voxels "${LINE_MIN_VOXELS:-3}" --edge_width_vox "${EDGE_WIDTH_VOX:-10}" --core_size "${CORE_SIZE:-48}" --batch_size "${INFER_BATCH:-5}" --build_workers "${BUILD_WORKERS:-6}" --compile_model "${TORCH_COMPILE:-1}" --resume "${RESUME:-1}" --missing_source_policy "${MISSING_SOURCE_POLICY:-skip}"
